using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

// --- 1. GetTypeInfo<T>(): strongly-typed metadata retrieval ---
var options = new JsonSerializerOptions(JsonSerializerDefaults.Web);

JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"GetTypeInfo<Person> returned type: {personInfo.Type.Name}");

string json = JsonSerializer.Serialize(new Person("Alice", 42), personInfo);
Console.WriteLine($"Serialized: {json}");

// --- 2. TryGetTypeInfo<T>(): check-without-throwing ---
// The default reflection resolver can resolve any type, so Person succeeds:
if (options.TryGetTypeInfo<Person>(out var info))
    Console.WriteLine($"TryGet Person  → found ({info!.Type.Name})");
else
    Console.WriteLine("TryGet Person  → not found");

// With a source-gen context that only knows about Person,
// an *unregistered* type will return false instead of throwing.
var limited = new JsonSerializerOptions { TypeInfoResolver = SmallContext.Default };

if (limited.TryGetTypeInfo<Person>(out var pInfo))
    Console.WriteLine($"TryGet Person  (limited) → found ({pInfo!.Type.Name})");
else
    Console.WriteLine("TryGet Person  (limited) → not found");

if (limited.TryGetTypeInfo<UnknownType>(out var uInfo))
    Console.WriteLine($"TryGet Unknown (limited) → found ({uInfo!.Type.Name})");
else
    Console.WriteLine("TryGet Unknown (limited) → not found  (no exception!)");

// --- Types & source-gen context ---
public record Person(string Name, int Age);
public record UnknownType(string Data);

[JsonSerializable(typeof(Person))]          // only Person is registered
public partial class SmallContext : JsonSerializerContext;

